3: namespace App\Services;
4: 
5: use Carbon\CarbonInterface;
6: use Illuminate\Support\Carbon;
7: use Illuminate\Support\Facades\DB;
8: use RuntimeException;
9: 
10: class NumberSequenceService
11: {
12:     /**
13:      * Ambil nomor berikutnya secara atomik (SELECT ... FOR UPDATE).
14:      */
15:     public function next(string $code, ?CarbonInterface $at = null): string
16:     {
17:         $at = $at ? Carbon::instance($at) : now('Asia/Jakarta');
18: 
19:         return DB::transaction(function () use ($code, $at): string {
20:             $sequence = DB::table('number_sequences')
21:                 ->where('code', $code)
22:                 ->lockForUpdate()
23:                 ->first();
24: 
25:             if (! $sequence) {
26:                 throw new RuntimeException("Nomor urut '{$code}' belum dikonfigurasi.");
27:             }
28: 
29:             $next = (int) $sequence->next_number;
30:             $reset = false;
31:             $lastReset = $sequence->last_reset_at ? Carbon::parse($sequence->last_reset_at) : null;
32: 
33:             if ($sequence->reset_period === 'yearly'
34:                 && (! $lastReset || $lastReset->year !== $at->year)) {
35:                 $next = 1;
36:                 $reset = true;
37:             }
38: 
39:             if ($sequence->reset_period === 'monthly'
40:                 && (! $lastReset || $lastReset->format('Y-m') !== $at->format('Y-m'))) {
41:                 $next = 1;
42:                 $reset = true;
43:             }
44: 
45:             $number = $this->format(
46:                 $sequence->pattern,
47:                 $sequence->prefix,
48:                 $next,
49:                 $sequence->padding,
50:                 $at
51:             );
52: 
53:             DB::table('number_sequences')->where('id', $sequence->id)->update([
54:                 'next_number' => $next + 1,
55:                 'last_reset_at' => $reset ? $at->toDateString() : $sequence->last_reset_at,
56:                 'updated_at' => now(),
57:             ]);
58: 
59:             return $number;
60:         });
61:     }
62: 
63:     public function format(
64:         string $pattern,
65:         ?string $prefix,
66:         int $number,
67:         int $padding,
68:         CarbonInterface $at
69:     ): string {
70:         $replaced = str_replace(
71:             ['{prefix}', '{year}', '{month}', '{day}'],
72:             [$prefix ?? '', $at->format('Y'), $at->format('m'), $at->format('d')],
73:             $pattern
74:         );
75: 
76:         return preg_replace_callback(
77:             '/\{seq(?::(\d+))?\}/',
78:             fn (array $match) => str_pad(
79:                 (string) $number,
80:                 isset($match[1]) && $match[1] !== '' ? (int) $match[1] : $padding,
81:                 '0',
82:                 STR_PAD_LEFT
83:             ),
84:             $replaced
85:         );
86:     }
87: }

