10: trait GuardsHrAccess
11: {
12:     protected function ensurePermission(Request $request, string $permission): void
13:     {
14:         abort_unless(
15:             $request->user()->hasPermission($permission),
16:             403,
17:             'Anda tidak memiliki hak akses untuk tindakan ini.'
18:         );
