21:     /**
22:      * Batasi data berdasarkan cakupan pegawai pengguna.
23:      */
24:     protected function scopeEmployeeRecords(Builder $query, User $user, string $column = 'employee_id'): Builder
25:     {
26:         if ($user->hasPermission('employee.view.all')) {
27:             return $query;
28:         }
29: 
30:         if ($user->hasPermission('employee.view.unit')) {
31:             return $query->whereIn($column, Employee::query()->visibleTo($user)->select('id'));
32:         }
33: 
34:         return $query->where($column, $user->employee_id ?? 0);
35:     }
36: 
37:     protected function ensureRecordVisible(Request $request, int $employeeId): void
38:     {
39:         $visible = Employee::query()
40:             ->visibleTo($request->user())
41:             ->whereKey($employeeId)
42:             ->exists();
43: 
44:         abort_unless($visible, 403, 'Anda tidak memiliki akses ke data pegawai ini.');
45:     }
46: }

