36:                         'absent_days' => $counts['tidak_hadir'] ?? 0, 'paid_leave_days' => ($counts['izin'] ?? 0) + ($counts['sakit'] ?? 0),
37:                         'unpaid_leave_days' => 0, 'holiday_days' => $counts['libur'] ?? 0, 'special_days' => $counts['dispensasi'] ?? 0,
38:                         'is_locked' => false, 'generated_at' => now(), 'generated_by' => $user->id,
39:                     ]
40:                 );
41:             }
42:             $period->update(['status' => 'dihitung']);
43:             $this->audit->recordRaw('payroll.snapshot.generated', PayrollPeriod::class, $period->id, null, ['employee_count' => $employees->count()]);
