49:     {
50:         if ($period->isLocked()) throw ValidationException::withMessages(['period' => 'Periode payroll sudah dikunci.']);
51:         if (! AttendancePeriodSummary::query()->where('payroll_period_id', $period->id)->exists()) throw ValidationException::withMessages(['period' => 'Buat snapshot absensi sebelum menghitung payroll.']);
52: 
53:         return DB::transaction(function () use ($period, $user) {
54:             $version = ((int) PayrollRun::query()->where('payroll_period_id', $period->id)->max('version')) + 1;
55:             $run = PayrollRun::query()->create(['payroll_period_id' => $period->id, 'version' => $version, 'status' => 'draf', 'calculated_by' => $user->id, 'calculated_at' => now()]);
