48:     public function calculateSkeleton(PayrollPeriod $period, User $user): PayrollRun
49:     {
50:         if ($period->isLocked()) throw ValidationException::withMessages(['period' => 'Periode payroll sudah dikunci.']);
51:         if (! AttendancePeriodSummary::query()->where('payroll_period_id', $period->id)->exists()) throw ValidationException::withMessages(['period' => 'Buat snapshot absensi sebelum menghitung payroll.']);
52: 
53:         return DB::transaction(function () use ($period, $user) {
54:             PayrollRun::query()
55:                 ->where('payroll_period_id', $period->id)
56:                 ->whereIn('status', ['draf', 'final'])
57:                 ->update(['status' => 'dibatalkan']);
58: 
59:             $version = ((int) PayrollRun::query()->where('payroll_period_id', $period->id)->max('version')) + 1;
60:             $run = PayrollRun::query()->create(['payroll_period_id' => $period->id, 'version' => $version, 'status' => 'draf', 'calculated_by' => $user->id, 'calculated_at' => now()]);
61:             $summaries = AttendancePeriodSummary::query()->where('payroll_period_id', $period->id)->get();
