100:                 'amount' => $adjustment->type === 'potongan' ? -abs($adjustment->amount) : abs($adjustment->amount),
101:                 'formula_note' => 'Penyesuaian disetujui: '.$adjustment->reason,
102:                 'source_type' => 'manual_adjustment',
