109:     private function refreshRunTotals(PayrollRun $run): void
110:     {
111:         $rows = $run->employees()->with('details')->get();
112:         $gross = $deduction = $employer = 0.0;
113:         foreach ($rows as $row) {
114:             $income = (float) $row->details->where('type', 'penghasilan')->sum('amount');
115:             $cuts = abs((float) $row->details->where('type', 'potongan')->sum('amount'));
116:             $employerForEmployee = (float) $row->details->where('type', 'iuran_pemberi')->sum('amount');
117:             $row->update(['gross' => $income, 'total_deduction' => $cuts, 'employer_contribution' => $employerForEmployee, 'net' => $income - $cuts]);
118:             $gross += $income; $deduction += $cuts; $employer += $employerForEmployee;
119:         }
120:         $run->update(['total_gross' => $gross, 'total_deduction' => $deduction, 'total_net' => $gross - $deduction, 'total_employer_contribution' => $employer]);
