private function prorationFactor(Employee $employee, PayrollPeriod $period): float
{
    $periodDays = $period->start_date->diffInDays($period->end_date) + 1;
    $activeStart = $employee->hire_date && $employee->hire_date->greaterThan($period->start_date)
        ? $employee->hire_date : $period->start_date;
    $activeEnd = $employee->termination_date && $employee->termination_date->lessThan($period->end_date)
        ? $employee->termination_date : $period->end_date;
    if ($activeEnd->lessThan($activeStart)) return 0.0;
    return min(1, max(0, ($activeStart->diffInDays($activeEnd) + 1) / max(1, $periodDays)));
}

private function formatFactor(float $factor): string
{
    return number_format($factor * 100, 2, ',', '.').'%';
}

