10: class Pph21Calculator
11: {
12:     public function calculate(Employee $employee, object $profile, float $grossIncome, Collection $components): ?array
13:     {
14:         $component = $components->get('pph21');
15:         if (! $component || $grossIncome <= 0) return null;
16: 
17:         $category = $this->terCategory($profile->tax_status ?? null, (int) ($profile->dependents_count ?? 0));
18:         $rate = $this->terRate($category, $grossIncome);
19:         if ($rate <= 0) return null;
20: 
21:         $amount = ceil($grossIncome * $rate);
22:         return [
23:             'component_id' => $component->id,
24:             'type' => $profile->tax_borne_by_employer ? 'iuran_pemberi' : 'potongan',
25:             'quantity' => 1,
26:             'unit_rate' => $rate * 100,
27:             'basis_amount' => $grossIncome,
28:             'amount' => $amount,
29:             'formula_note' => 'PPh 21 TER Kategori '.$category.' ('.number_format($rate * 100, 2, ',', '.').'%)',
30:             'source_type' => 'pph21_calculator',
31:             'source_id' => null,
32:             'sort_order' => $component->sort_order,
33:         ];
34:     }
