36:     public function terCategory(?string $taxStatus, int $dependents): string
37:     {
38:         $status = strtoupper(trim((string) $taxStatus));
39:         if ($status === '') {
40:             $status = $dependents <= 0 ? 'TK/0' : ($dependents === 1 ? 'TK/1' : 'K/'.$dependents);
41:         }
42:         return match ($status) {
43:             'TK/0', 'TK/1', 'K/0' => 'A',
44:             'TK/2', 'TK/3', 'K/1', 'K/2' => 'B',
45:             'K/3' => 'C',
46:             default => 'A',
47:         };
48:     }
