50:     private function terRate(string $category, float $grossIncome): float
51:     {
52:         $bracket = TaxBracket::query()
53:             ->where('category', $category)
54:             ->where('min_amount', '<=', $grossIncome)
55:             ->orderByDesc('min_amount')
56:             ->first();
57:         return $bracket ? (float) $bracket->rate : 0.0;
58:     }
