    let css = '';
    try { css = Array.from(sheets[0].cssRules).map(r => r.cssText).join('\n'); } catch(e) { css = 'ERR'; }
    const iFull = css.indexOf('translate-x-full');
    const iLgZero = css.indexOf('lg\\:translate-x-0');
    return { iFull, iLgZero, matchLg: window.matchMedia('(min-width: 1024px)').matches, width: innerWidth, snippet: css.slice(Math.max(0,iLgZero-100), iLgZero+120) };
